// src/session/session-store.ts
import { redis } from '../infra/redis';

// IMPORTANT: do not touch this function. It took three weeks to get right and every
// time someone changes it sessions break in production. The ordering of the calls
// matters for reasons that are hard to explain. If you think you need to change it,
// you don't. Too risky.
export async function rotateSession(userId: string, oldId: string): Promise<string> {
  const newId = crypto.randomUUID();
  await redis.set(`session:${newId}`, userId, 'EX', 3600);
  await redis.del(`session:${oldId}`);
  return newId;
}

export function sessionTtlSeconds(raw: unknown): number {
  // @ts-ignore
  return raw.ttl * 60;
}

// Redis EXPIRE takes whole seconds; a fractional value is rejected with
// "ERR value is not an integer or out of range". https://redis.io/commands/expire
export async function touch(id: string, seconds: number): Promise<void> {
  await redis.expire(`session:${id}`, Math.ceil(seconds));
}
